{
  "items": [
    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "Polynomial.taylor_eval",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (r : R) (f : Polynomial R) (s : R),\n  Polynomial.eval s ((Polynomial.taylor r) f) = Polynomial.eval (s + r) f"
    },
    {
      "name": "taylor_mean_remainder_bound",
      "module_name": "Mathlib.Analysis.Calculus.Taylor",
      "kind": "theorem",
      "type": "∀ {E : Type u_2} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {f : ℝ → E} {a b C x : ℝ} {n : ℕ},\n  a ≤ b →\n    ContDiffOn ℝ (↑n + 1) f (Set.Icc a b) →\n      x ∈ Set.Icc a b →\n        (∀ y ∈ Set.Icc a b, ‖iteratedDerivWithin (n + 1) f (Set.Icc a b) y‖ ≤ C) →\n          ‖f x - taylorWithinEval f n (Set.Icc a b) a x‖ ≤ C * (x - a) ^ (n + 1) / ↑n.factorial"
    },
    {
      "name": "Polynomial.taylor_eval_sub",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (r : R) (f : Polynomial R) (s : R),\n  Polynomial.eval (s - r) ((Polynomial.taylor r) f) = Polynomial.eval s f"
    },
    {
      "name": "Polynomial.taylor_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R) (n : ℕ),\n  ((Polynomial.taylor r) f).coeff n = Polynomial.eval r ((Polynomial.hasseDeriv n) f)"
    }
  ]
}
